PROGRAM = "sensex-readonly-observer"
VERSION = "6.0"
EXIT_OK, EXIT_CONFIG, EXIT_AUTH, EXIT_SELFTEST = 0, 2, 3, 4


def _stdout_logger(redactor):
    return JsonLogger(redactor, stream=sys.stdout, prefix="BX|")


def _runtime(log):
    log("info", "runtime", program=PROGRAM, version=VERSION, mode=MODE, python=sys.version.split()[0],
        implementation=sys.implementation.name, platform=sys.platform,
        utc=datetime.now(timezone.utc).isoformat(timespec="seconds"),
        allowList=sorted("%s %s" % k for k in READ_ONLY_ENDPOINTS), orders="NONE (no order code present)")


class _FixedTransport:
    """Serves the embedded MOCK bodies; no network."""

    def __init__(self, bodies, receipts, default_ms):
        self.bodies, self.receipts, self.default_ms = bodies, receipts, default_ms

    def send(self, method, url, headers, body, timeout):
        path = url.split("/v2", 1)[1]
        if path not in self.bodies:
            return RawResponse(404, b"{}", {}, self.default_ms)
        return RawResponse(200, json.dumps(self.bodies[path]).encode(), {}, self.receipts.get(path, self.default_ms))


def validate(log) -> int:
    """Offline self-test: the bundled engine must reproduce the expected table
    on the embedded MOCK snapshot (Stage A scenario s21Sep)."""
    st = SELFTEST
    t = _FixedTransport(st["bodies"], {k: int(v) for k, v in st["receipts"].items()}, int(st["receipts"]["/optionchain"]))
    sim = [0.0]
    from bx_dhan_client import RateLimiter
    lim = RateLimiter(clock=lambda: sim[0], sleep=lambda s: sim.__setitem__(0, sim[0] + s))
    red = Redactor()
    client = DhanClient(Credentials("SELFTEST", "selftest-not-a-credential"), transport=t, limiter=lim,
                        redactor=red, sleep=lambda s: None)
    at = datetime.fromisoformat(st["clockUtc"])
    cfg = ScannerConfig(strikes=st["strikes"], futures_security_id=st["futuresSecurityId"],
                        futures_expiry=st["futuresExpiry"], ignore_session=True, max_scans=1)

    class _Quiet:
        def __call__(self, *a, **k):
            pass
    rec = Scanner(client, cfg, _Quiet(), clock=lambda: at).run_once()
    ok = rec["status"] == "OK" and rec["table"] == st["expectedTable"]
    log("info" if ok else "error", "selftest", data="MOCK (embedded Stage A s21Sep; not market data)",
        result="PASS" if ok else "FAIL", status=rec["status"], table=rec["table"],
        observationKeys=sorted(rec.get("observation", {}).keys()))
    cred_names = {n: (n in os.environ) for n in (ENV_CLIENT_ID, ENV_ACCESS_TOKEN)}
    log("info", "credential_names_present", **cred_names)   # names and presence only, never values
    return EXIT_OK if ok else EXIT_SELFTEST


def _config_errors():
    errs = []
    if not STRIKES:
        errs.append("STRIKES is empty (ATM±2 rule undefined; list strikes explicitly)")
    if not FUTURES_SECURITY_ID or not FUTURES_EXPIRY:
        errs.append("FUTURES_SECURITY_ID / FUTURES_EXPIRY not set (automatic lookup is BLOCKED)")
    if INTERVAL_S < 10:
        errs.append("INTERVAL_S must be >= 10")
    return errs


def _emit_record(scanner_rec, recorder, cfg, clock_utc, log_line):
    """Chunked, gzip+base64 replay record: market-data bodies only."""
    payload = {"scanId": scanner_rec["scanId"], "meta": {"strikes": cfg.strikes,
               "futuresSecurityId": cfg.futures_security_id, "futuresExpiry": cfg.futures_expiry,
               "clockUtc": clock_utc}}
    payload.update(recorder.take())
    blob = base64.b64encode(gzip.compress(json.dumps(payload).encode("utf-8"))).decode("ascii")
    parts = [blob[i:i + RECORD_CHUNK] for i in range(0, len(blob), RECORD_CHUNK)] or [""]
    for i, part in enumerate(parts, 1):
        log_line("BX|REC|%s|%d/%d|%s" % (scanner_rec["scanId"], i, len(parts), part))


def live(log, redactor, loop: bool) -> int:
    errs = _config_errors()
    if errs:
        log("error", "config_blocked", errors=errs)
        return EXIT_CONFIG
    try:
        creds = Credentials.from_environment({"DHAN_CLIENT_ID": os.environ.get(ENV_CLIENT_ID, ""),
                                              "DHAN_ACCESS_TOKEN": os.environ.get(ENV_ACCESS_TOKEN, "")})
    except AuthError:
        log("error", "credentials_missing", expected_names=[ENV_CLIENT_ID, ENV_ACCESS_TOKEN],
            present={n: (n in os.environ) for n in (ENV_CLIENT_ID, ENV_ACCESS_TOKEN)})
        return EXIT_AUTH
    redactor.register(creds.access_token, creds.client_id)
    exp = creds.token_expiry_ms()
    now_ms = time.time() * 1000
    if exp is not None and exp <= now_ms:
        log("error", "token_expired", hours_ago=round((now_ms - exp) / 3.6e6, 2),
            action="Generate a new token in Dhan web and update the Cloud variable %s" % ENV_ACCESS_TOKEN)
        return EXIT_AUTH
    log("info", "token_status", hours_left=None if exp is None else round((exp - now_ms) / 3.6e6, 2))

    recorder = MemoryRecorder(UrllibTransport())
    client = DhanClient(creds, transport=recorder, redactor=redactor, logger=log)
    hh, mm = (int(x) for x in STOP_TIME.split(":"))
    cfg = ScannerConfig(strikes=[float(s) for s in STRIKES], interval_s=float(INTERVAL_S), stop_time=dtime(hh, mm),
                        holidays=frozenset(HOLIDAYS), futures_security_id=str(FUTURES_SECURITY_ID),
                        futures_expiry=FUTURES_EXPIRY, max_scans=None if loop else 1,
                        observe_leg_band=int(LEG_BAND))
    scanner = Scanner(client, cfg, log)

    def line(text):
        sys.stdout.write(redactor(text) + "\n")
        sys.stdout.flush()

    def on_record(rec):
        n = rec["scan"]
        if RECORD_EVERY_N and rec["status"] != "SKIPPED" and (
                rec["status"] != "OK" or n == 1 or n % RECORD_EVERY_N == 0):
            _emit_record(rec, recorder, cfg, rec["clockUtc"], line)
        else:
            recorder.take()

    reason = scanner.run_loop(on_record=on_record)
    h = scanner.state.history
    log("info", "session_summary", stopReason=reason, scans=len(h),
        statusCounts={s: h.count(s) for s in sorted(set(h))}, ordersPlaced=0,
        strategy="NO_SIGNAL (direction thresholds not configured)")
    return EXIT_AUTH if reason in ("AUTH_FAILED", "PLAN_MISSING") else EXIT_OK


def main() -> int:
    redactor = Redactor()
    log = _stdout_logger(redactor)
    _runtime(log)
    if MODE == "VALIDATE":
        return validate(log)
    if MODE in ("LIVE_CHECK", "OBSERVE"):
        return live(log, redactor, loop=MODE == "OBSERVE")
    log("error", "config_blocked", errors=["MODE must be VALIDATE, LIVE_CHECK or OBSERVE"])
    return EXIT_CONFIG


if __name__ == "__main__":
    sys.exit(main())
